SELECT ?entity ?entityLabel ?entityDescription ?sitelinks ?enwiki (GROUP_CONCAT(DISTINCT STR(?alias); separator="|") AS ?aliases) WHERE {
  ?entity wdt:P31 wd:Q6256 ; wikibase:sitelinks ?sitelinks ; rdfs:label ?entityLabel .
  FILTER(?sitelinks >= 0)
  FILTER(LANG(?entityLabel) = "en")
  OPTIONAL { ?entity schema:description ?entityDescription . FILTER(LANG(?entityDescription) = "en") }
  OPTIONAL { ?enwiki schema:about ?entity ; schema:isPartOf <https://en.wikipedia.org/> . }
  OPTIONAL { ?entity skos:altLabel ?alias . FILTER(LANG(?alias) = "en") }
}
GROUP BY ?entity ?entityLabel ?entityDescription ?sitelinks ?enwiki
ORDER BY ?entity

